#include <cassert>
#include <cstdint>
#include <limits>
#ifdef NDEBUG
#error Tests require assertions enabled
#endif
enum class Policy { AllowFall, StopAtEdge };
struct Result { bool valid; std::int64_t x; bool supported; bool blocked; };
// One horizontal step from a supported point foot on a single closed interval.
// Coordinates are fixed-point integer units. No body width, slope, or gravity.
Result Step(int oldX, int delta, int left, int right, Policy policy) {
    if (left > right || oldX < left || oldX > right)
        return {false, oldX, false, false};
    const std::int64_t next = static_cast<std::int64_t>(oldX) + delta;
    const bool inside = next >= left && next <= right;
    if (inside || policy == Policy::AllowFall)
        return {true, next, inside, false};
    return {true, next < left ? left : right, true, true};
}
int main() {
    Result r = Step(9, 1, 0, 10, Policy::AllowFall);
    assert(r.valid && r.x == 10 && r.supported && !r.blocked);
    r = Step(9, 2, 0, 10, Policy::AllowFall);
    assert(r.valid && r.x == 11 && !r.supported && !r.blocked);
    r = Step(9, 2, 0, 10, Policy::StopAtEdge);
    assert(r.valid && r.x == 10 && r.supported && r.blocked);
    r = Step(1, -5, 0, 10, Policy::StopAtEdge);
    assert(r.x == 0 && r.supported && r.blocked);
    assert(!Step(11, 0, 0, 10, Policy::AllowFall).valid);
    assert(!Step(0, 0, 10, 0, Policy::StopAtEdge).valid);
    assert(Step(4, 0, 4, 4, Policy::StopAtEdge).supported);
    const int hi = std::numeric_limits<int>::max();
    r = Step(hi, hi, 0, hi, Policy::AllowFall);
    assert(r.x == 2LL * hi && !r.supported);
    for (int x=0; x<=10; ++x) for (int delta=-100; delta<=100; ++delta) {
        r = Step(x, delta, 0, 10, Policy::StopAtEdge);
        assert(r.valid && r.supported && r.x>=0 && r.x<=10);
    }
}
